\documentclass{beamer}
\usetheme{Madrid}
\usepackage{amsmath}
\title{CE 5721 --- Traffic Flow Theory}
\subtitle{Week 6: The Fundamental Diagram and Shockwaves}
\author{Y. Lindqvist}
\date{Autumn 2026}

\begin{document}

\begin{frame}
\titlepage
\end{frame}

\begin{frame}{Outline}
\tableofcontents
\end{frame}

\section{Macroscopic Variables}

\begin{frame}{Three Macroscopic Variables}
Traffic on a road section is described by three linked quantities:
\begin{itemize}
\item flow $q$ (vehicles per hour),
\item density $k$ (vehicles per kilometre),
\item space-mean speed $v$ (kilometres per hour).
\end{itemize}
They obey the hydrodynamic identity
\begin{equation}
q = k \, v
\end{equation}
at every point of the time--space plane.
\end{frame}

\section{The Fundamental Diagram}

\begin{frame}{Greenshields' Linear Model}
Under the linear speed--density hypothesis,
\begin{equation}
v = v_f \left( 1 - \frac{k}{k_j} \right),
\end{equation}
where $v_f$ is the free-flow speed and $k_j$ the jam density.
Substituting into $q = k v$ gives a parabolic flow--density curve
with capacity $q_{\max} = v_f k_j / 4$ at $k = k_j / 2$.
\end{frame}

\begin{frame}{Free-Flow and Congested Branches}
\begin{columns}
\column{0.48}
The free-flow branch rises from the origin to capacity;
traffic states here are stable and self-organising.
\column{0.48\textwidth}
The congested branch falls from capacity to the jam point;
stop-and-go waves appear here without any external trigger.
\end{columns}
\end{frame}

\section{Shockwaves}

\begin{frame}{Shockwave Speed}
A shockwave separates two traffic states $(q_1, k_1)$ and $(q_2, k_2)$.
Its speed is the slope of the chord joining them:
\begin{equation}
w = \frac{q_2 - q_1}{k_2 - k_1}.
\end{equation}
A negative $w$ means the queue boundary moves upstream against the traffic.
\end{frame}

\begin{frame}{Work Zone Example}
A lane closure drops capacity to 900~veh/h.
If demand stays at 1400~veh/h, the queue grows at
$1400 - 900 = 500$~veh/h
and the shockwave travels upstream at about $-12$~km/h.
\end{frame}

\section{Field Measurement}

\begin{frame}{Loop Detector Output}
A single inductive loop reports occupancy and count every 60 seconds.
The raw export for one morning peak looks like this:
\begin{verbatim}
07:02  lane2  occ=0.11  count=22
07:03  lane2  occ=0.13  count=24
07:04  lane2  occ=0.19  count=23
\end{verbatim}
Occupancy is converted to density with the effective vehicle length.
\end{frame}

\section{Summary}

\begin{frame}{Summary}
\begin{itemize}
\item The fundamental diagram ties $q$, $k$ and $v$ into one curve.
\item Shockwaves are chords on that diagram.
\item Loop data calibrate the diagram for a real section.
\end{itemize}
Next week: kinematic wave theory and the LWR model.
\end{frame}

\end{document}

